    let text;
    if (!status.enabled) {
      text = status.silent ? "Off \u2014 pick a folder to auto-save an encrypted copy." : "Off \u2014 save an encrypted copy to a folder you choose.";
    } else if (status.needsPermission) {
      text = `Reconnect needed \u2014 click Save now to re-grant access${status.folderName ? ` to \u201C${status.folderName}\u201D` : ""}.`;
    } else {
      const where = status.folderName ? `\u201C${status.folderName}\u201D` : "your chosen folder";
      const when = status.lastWriteAt ? ` \xB7 last saved ${new Date(status.lastWriteAt).toLocaleString()}` : "";
      text = status.silent ? `On \u2014 auto-saving to ${where}${when}.` : `On \u2014 save/restore manually to ${where}${when}.`;
    }
    elements.cloudBackupStatus.textContent = text;
